 {"id": "PEDS-C2-059", "sec": "Bag and Mask Ventilation", "page": 9, "q": "For a baby of >= 35 weeks, the FiO2 started with is ___", "opts": ["60% O2", "100% O2", "40% O2", "Room air"], "ans": 3, "exp": "FiO2: >= 35 weeks room air (21% O2). (Book p9)", "type": "fill"},
