 {"id": "PEDS-C2-076", "sec": "Ventilation Correction Steps", "page": 9, "q": "'S' in MRSOPA stands for ___", "opts": ["Suction: remove all secretions", "Slow the rate", "Switch tube", "40 to 60 breaths/min"], "ans": 0, "exp": "S: suction - remove all secretions. (Book p9)", "type": "fill"},
 {"type": "match", "sec": "Ventilation Correction Steps", "page": 9, "q": "Match Column A with Column B — select the correctly matched combination:", "pairs": [["'M' in MRSOPA", "Readjust head position"], ["M/c cause of inadequate response to BMV", "Suction: remove all secretions"], ["'R' in MRSOPA", "Incorrect mask position"], ["'S' in MRSOPA", "Mask repositioning"]], "opts": ["A-4, B-2, C-3, D-1", "A-1, B-3, C-4, D-2", "A-4, B-3, C-1, D-2", "A-3, B-4, C-2, D-1"], "ans": 2, "exp": "Correct pairs: 'M' in MRSOPA→Mask repositioning; M/c cause of inadequate response to BMV→Incorrect mask position; 'R' in MRSOPA→Readjust head position; 'S' in MRSOPA→Suction: remove all secretions. (Book p9)", "id": "PEDS-C2-077"},
