 {"id": "PEDS-C2-079", "sec": "Ventilation Correction Steps", "page": 9, "q": "'P' in MRSOPA stands for ___", "opts": ["Pneumothorax check", "Propranolol", "PPV", "Pressure increase over bag"], "ans": 3, "exp": "P: pressure increase over bag. (Book p9)", "type": "fill"},
